// @ts-ignore - generated by opennextjs-cloudflare during build
import openNextWorker from "./.open-next/worker.js";
import { handleEmailQueue } from "./src/lib/email-queue-consumer";

interface D1Statement {
  bind(...values: unknown[]): D1Statement;
  first<T = Record<string, unknown>>(): Promise<T | null>;
  run(): Promise<unknown>;
}
interface D1Database { prepare(sql: string): D1Statement; }
interface EmailAttachment {
  filename: string;
  contentBase64: string;
  contentType?: string;
  disposition?: "attachment" | "inline";
  cid?: string;
}
interface EmailQueueMessage {
  logId: string;
  to: string;
  from: string;
  subject: string;
  html: string;
  attachments?: EmailAttachment[];
}
interface QueueMessage<T> {
  body: T; attempts: number; ack(): void;
  retry(options?: { delaySeconds?: number }): void;
}
interface QueueBatch<T> { queue: string; messages: QueueMessage<T>[]; }
interface WorkerEnv {
  DB: D1Database;
  VPS_MAIL_API_URL?: string;
  VPS_MAIL_API_KEY?: string;
  VPS_MAIL_FROM_EMAIL?: string;
}
export default {
  fetch(request: Request, env: WorkerEnv, ctx: unknown): Promise<Response> {
    return openNextWorker.fetch(request, env, ctx);
  },
  async queue(batch: QueueBatch<EmailQueueMessage>, env: WorkerEnv): Promise<void> {
    await handleEmailQueue(batch, env);
  },
};